begin; do $$ begin if to_regclass('public._test_db_marker') is null then raise exception 'STOP: test DB marker not found. This SQL is only for the test project.'; end if; end; $$; alter table students add column if not exists status text not null default 'active'; alter table students add column if not exists withdrawn_on date; alter table students add column if not exists withdraw_note text; alter table students drop constraint if exists students_status_check; alter table students add constraint students_status_check check (status in ('active', 'paused', 'withdrawn')); drop policy if exists "update_own_students" on students; create policy "update_own_students" on students for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid()); create table if not exists classes ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete restrict, name text not null check (length(btrim(name)) > 0), target_grades text[] not null default '{}' check (target_grades <@ array['초3', '초4', '초5', '초6', '중1', '중2', '중3', '고1', '고2', '고3']::text[]), teacher_name text, status text not null default 'active' check (status in ('active', 'closed')), closed_on date, note text, created_at timestamptz not null default now(), check ((status = 'closed') = (closed_on is not null)) ); create table if not exists class_schedules ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete restrict, class_id uuid not null references classes(id) on delete restrict, weekday smallint not null check (weekday between 1 and 7), start_time time not null, end_time time not null, check (end_time > start_time) ); create table if not exists class_students ( id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete restrict, class_id uuid not null references classes(id) on delete restrict, student_id uuid not null references students(id) on delete restrict, joined_on date not null default ((now() at time zone 'Asia/Seoul')::date), left_on date, check (left_on is null or left_on >= joined_on) ); create unique index if not exists class_students_one_open on class_students (class_id, student_id) where left_on is null; create index if not exists classes_user_id_idx on classes (user_id); create index if not exists class_schedules_class_id_idx on class_schedules (class_id); create index if not exists class_students_student_id_idx on class_students (student_id); alter table classes enable row level security; alter table class_schedules enable row level security; alter table class_students enable row level security; grant select, insert, update on classes to authenticated; grant select, insert, update, delete on class_schedules to authenticated; grant select, insert, update on class_students to authenticated; drop policy if exists "classes_select_own" on classes; create policy "classes_select_own" on classes for select to authenticated using (user_id = auth.uid()); drop policy if exists "classes_insert_own" on classes; create policy "classes_insert_own" on classes for insert to authenticated with check (user_id = auth.uid()); drop policy if exists "classes_update_own" on classes; create policy "classes_update_own" on classes for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid()); drop policy if exists "class_schedules_own" on class_schedules; create policy "class_schedules_own" on class_schedules for all to authenticated using (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid())) with check (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid())); drop policy if exists "class_students_select_own" on class_students; create policy "class_students_select_own" on class_students for select to authenticated using (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid()) and exists (select 1 from students s where s.id = student_id and s.user_id = auth.uid())); drop policy if exists "class_students_insert_own" on class_students; create policy "class_students_insert_own" on class_students for insert to authenticated with check (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid()) and exists (select 1 from students s where s.id = student_id and s.user_id = auth.uid())); drop policy if exists "class_students_update_own" on class_students; create policy "class_students_update_own" on class_students for update to authenticated using (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid()) and exists (select 1 from students s where s.id = student_id and s.user_id = auth.uid())) with check (user_id = auth.uid() and exists (select 1 from classes c where c.id = class_id and c.user_id = auth.uid()) and exists (select 1 from students s where s.id = student_id and s.user_id = auth.uid())); create or replace function withdraw_student(p_student_id uuid, p_withdrawn_on date, p_note text default null) returns integer language plpgsql security invoker set search_path = public as $$ declare closed_count integer; begin if p_withdrawn_on is null then raise exception 'withdrawn_on is required' using errcode = '22023'; end if; update students set status = 'withdrawn', withdrawn_on = p_withdrawn_on, withdraw_note = nullif(btrim(p_note), '') where id = p_student_id and user_id = auth.uid() and status <> 'withdrawn'; if not found then raise exception 'student not found or already withdrawn' using errcode = 'P0002'; end if; update class_students set left_on = greatest(joined_on, p_withdrawn_on) where student_id = p_student_id and user_id = auth.uid() and left_on is null; get diagnostics closed_count = row_count; return closed_count; end; $$; revoke all on function withdraw_student(uuid, date, text) from public, anon; grant execute on function withdraw_student(uuid, date, text) to authenticated; commit;
